#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024          /* 0x400 bytes – strings must be shorter than 0x401 */

int main(int argc, char *argv[])
{
    /* --------------------------------------------------------------
       Argument handling – the original program prints "USAGE" when
       it receives fewer than two strings (i.e. argc < 3).  Extra
       arguments are ignored, exactly like the original binary.
       -------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    /* --------------------------------------------------------------
       Length checks – both input strings must be shorter than 0x401
       (1025) characters.  If either is too long the program prints
       "TOO_LONG".
       -------------------------------------------------------------- */
    if (strlen(s1) >= MAX_LEN + 1 || strlen(s2) >= MAX_LEN + 1) {
        puts("TOO_LONG");
        return 0;
    }

    /* --------------------------------------------------------------
       Frequency table (256 entries).  The original code:
         * ignores spaces,
         * treats letters case‑insensitively (A‑Z are converted to a‑z),
         * counts every other byte value as‑is.
       -------------------------------------------------------------- */
    int freq[256] = {0};

    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ')               /* spaces are ignored */
            continue;
        if (c >= 'A' && c <= 'Z')   /* case‑insensitive for letters */
            c = (unsigned char)(c + ('a' - 'A'));
        ++freq[c];
    }

    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ')               /* spaces are ignored */
            continue;
        if (c >= 'A' && c <= 'Z')
            c = (unsigned char)(c + ('a' - 'A'));
        --freq[c];
    }

    /* --------------------------------------------------------------
       Determine result – if any entry is non‑zero the strings are not
       anagrams of each other.
       -------------------------------------------------------------- */
    const char *msg = "ANAGRAM";
    for (int i = 0; i < 256; ++i) {
        if (freq[i] != 0) {
            msg = "NOT_ANAGRAM";
            break;
        }
    }

    puts(msg);
    return 0;
}
